def cluster_texts(t):
 n=len(t)
 if n<3:return list(range(n))
 D=[prep(x if isinstance(x,str)else str(x))for x in t];k=np.array([len(x)>0 for x in D])
 if k.sum()<3:return[0]*n
 s=[x for x in D if x];r=[x for x,m in zip(t,k)if m]
